#include <bits/stdc++.h>
using namespace std;

int main(void){
	int n,x;
	int a[50];
	int b[50];
	bool dp[51][10001];

	cin>>n>>x;
	for(int i=0;i<n;i++)cin>>a[i]>>b[i];

	for(int i=0;i<=n;i++)for(int j=0;j<=x;j++)dp[i][j]=false;
	dp[0][0]=true;
	for(int i=0;i<n;i++){
		for(int j=0;j<=x;j++){
			for(int k=0;k<=b[i];k++){
				if(j>=a[i]*k){
					if(dp[i][j-a[i]*k])dp[i+1][j]=true;
				}
			}
		}
	}

	if(dp[n][x])cout<<"Yes"<<endl;
	else cout<<"No"<<endl;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(void){
	int n,x;
	int a[50];
	int b[50];
	bool dp[10001]; //配列は使い回し
	int mx[100];

	cin>>n>>x;
	for(int i=0;i<n;i++)cin>>a[i]>>b[i];

	for(int i=0;i<=x;i++)dp[i]=false;
	dp[0]=true;
	for(int i=0;i<n;i++){
		for(int j=0;j<a[i];j++)mx[j]=-10000; //-a[i]*b[i]未満なら良い
		for(int j=0;j<=x;j++){
			if(dp[j])mx[j%a[i]]=j;
			if(mx[j%a[i]]>=j-(a[i]*b[i]))dp[j]=true;
			else dp[j]=false;
		}
	}

	if(dp[x])cout<<"Yes"<<endl;
	else cout<<"No"<<endl;
	return 0;
}
